const html = "<!doctype html>\n<html lang=\"zh-Hant\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>RO樂園煉金製藥成本表</title>\n  <style>\n    :root {\n      color-scheme: light;\n      --bg: #f4f0e8;\n      --paper: #fffdf8;\n      --ink: #20242a;\n      --muted: #66707b;\n      --line: #ded5c8;\n      --accent: #9c2f24;\n      --accent-2: #1f756b;\n      --gold: #b98520;\n      --green: #247a45;\n      --red: #b8382d;\n      --field: #fffaf1;\n      --shadow: 0 18px 45px rgba(43, 35, 26, 0.12);\n      --radius: 8px;\n    }\n\n    * { box-sizing: border-box; }\n\n    body {\n      margin: 0;\n      min-height: 100vh;\n      font-family: \"Microsoft JhengHei\", \"Noto Sans TC\", system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n      background:\n        linear-gradient(135deg, rgba(156, 47, 36, 0.10), transparent 33%),\n        linear-gradient(315deg, rgba(31, 117, 107, 0.10), transparent 36%),\n        var(--bg);\n      color: var(--ink);\n    }\n\n    a { color: inherit; }\n\n    .shell {\n      width: min(1180px, calc(100% - 28px));\n      margin: 0 auto;\n      padding: 26px 0 38px;\n    }\n\n    .topbar {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 14px;\n      margin-bottom: 14px;\n    }\n\n    .brand {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      min-width: 0;\n    }\n\n    .mark {\n      display: grid;\n      place-items: center;\n      flex: 0 0 auto;\n      width: 44px;\n      height: 44px;\n      border: 1px solid rgba(156, 47, 36, 0.28);\n      border-radius: var(--radius);\n      background: #fff4df;\n      color: var(--accent);\n      font-weight: 900;\n      box-shadow: inset 0 0 0 3px rgba(185, 133, 32, 0.14);\n    }\n\n    h1 {\n      margin: 0;\n      font-size: clamp(25px, 4vw, 42px);\n      line-height: 1.12;\n      letter-spacing: 0;\n    }\n\n    .subtitle {\n      margin: 5px 0 0;\n      color: var(--muted);\n      line-height: 1.55;\n      font-size: 14px;\n    }\n\n    .home-link,\n    .pill {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      min-height: 36px;\n      padding: 8px 11px;\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: rgba(255, 253, 248, 0.84);\n      color: var(--accent);\n      text-decoration: none;\n      font-size: 13px;\n      font-weight: 900;\n      white-space: nowrap;\n    }\n\n    .hero {\n      display: grid;\n      grid-template-columns: minmax(0, 1fr) 360px;\n      gap: 16px;\n      align-items: stretch;\n      margin-bottom: 14px;\n    }\n\n    .panel {\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: rgba(255, 253, 248, 0.92);\n      box-shadow: var(--shadow);\n    }\n\n    .hero-main {\n      padding: 22px;\n      background:\n        linear-gradient(115deg, rgba(255, 253, 248, 0.96), rgba(255, 253, 248, 0.84)),\n        linear-gradient(135deg, rgba(156, 47, 36, 0.10), rgba(31, 117, 107, 0.10));\n    }\n\n    .hero-main h2 {\n      margin: 0;\n      font-size: clamp(30px, 5vw, 54px);\n      line-height: 1.05;\n      letter-spacing: 0;\n    }\n\n    .hero-main p {\n      max-width: 760px;\n      margin: 12px 0 0;\n      color: var(--muted);\n      line-height: 1.75;\n      font-size: 15px;\n    }\n\n    .result-card {\n      display: grid;\n      align-content: center;\n      gap: 12px;\n      padding: 18px;\n      background:\n        linear-gradient(145deg, rgba(32, 36, 42, 0.96), rgba(44, 49, 56, 0.92)),\n        #20242a;\n      color: #fff;\n    }\n\n    .result-card span {\n      color: rgba(255, 255, 255, 0.70);\n      font-size: 13px;\n      font-weight: 900;\n    }\n\n    .result-number {\n      font-size: clamp(40px, 7vw, 68px);\n      font-weight: 900;\n      line-height: 0.95;\n      color: #ffe5a3;\n    }\n\n    .result-card p {\n      margin: 0;\n      color: rgba(255, 255, 255, 0.78);\n      font-size: 13px;\n      line-height: 1.65;\n    }\n\n    .quick-grid,\n    .main-grid,\n    .assumption-grid {\n      display: grid;\n      gap: 14px;\n      margin-bottom: 14px;\n    }\n\n    .quick-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }\n    .main-grid { grid-template-columns: 380px minmax(0, 1fr); align-items: start; }\n    .assumption-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n\n    .metric {\n      padding: 14px;\n    }\n\n    .metric dt {\n      margin: 0 0 5px;\n      color: var(--muted);\n      font-size: 12px;\n      font-weight: 900;\n    }\n\n    .metric dd {\n      margin: 0;\n      font-size: clamp(21px, 3vw, 30px);\n      font-weight: 900;\n      line-height: 1.1;\n    }\n\n    .metric small {\n      display: block;\n      margin-top: 5px;\n      color: var(--muted);\n      font-size: 12px;\n      line-height: 1.45;\n    }\n\n    .card {\n      padding: 16px;\n    }\n\n    .card h2,\n    .card h3 {\n      margin: 0 0 12px;\n      font-size: 21px;\n      line-height: 1.2;\n      letter-spacing: 0;\n    }\n\n    .card h3 { font-size: 17px; }\n\n    .note {\n      margin: 10px 0 0;\n      color: var(--muted);\n      font-size: 13px;\n      line-height: 1.65;\n    }\n\n    .controls {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 10px;\n    }\n\n    label {\n      display: grid;\n      gap: 5px;\n      color: var(--muted);\n      font-size: 12px;\n      font-weight: 900;\n    }\n\n    input,\n    select {\n      width: 100%;\n      min-height: 38px;\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: var(--field);\n      color: var(--ink);\n      padding: 8px 10px;\n      font: inherit;\n      font-size: 14px;\n      font-weight: 800;\n    }\n\n    input:focus,\n    select:focus {\n      outline: 2px solid rgba(31, 117, 107, 0.22);\n      border-color: rgba(31, 117, 107, 0.55);\n    }\n\n    .toggle-row {\n      display: grid;\n      gap: 8px;\n      margin-top: 12px;\n    }\n\n    .check {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      min-height: 38px;\n      gap: 10px;\n      padding: 8px 10px;\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: #fffaf1;\n      color: var(--ink);\n      font-size: 13px;\n      font-weight: 900;\n    }\n\n    .check input {\n      width: 18px;\n      height: 18px;\n      min-height: 0;\n      accent-color: var(--accent-2);\n    }\n\n    .table-wrap {\n      overflow-x: auto;\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: var(--paper);\n    }\n\n    table {\n      width: 100%;\n      min-width: 760px;\n      border-collapse: collapse;\n      font-size: 14px;\n    }\n\n    th,\n    td {\n      padding: 11px 12px;\n      border-bottom: 1px solid var(--line);\n      text-align: right;\n      vertical-align: middle;\n      white-space: nowrap;\n    }\n\n    th:first-child,\n    td:first-child,\n    th:nth-child(2),\n    td:nth-child(2) {\n      text-align: left;\n      white-space: normal;\n    }\n\n    th {\n      background: #2d3940;\n      color: #fff;\n      font-size: 12px;\n      font-weight: 900;\n    }\n\n    tr:last-child td { border-bottom: 0; }\n\n    td strong { color: var(--accent); }\n    .good { color: var(--green); font-weight: 900; }\n    .bad { color: var(--red); font-weight: 900; }\n\n    .formula {\n      margin: 0;\n      padding: 12px;\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: #fffaf1;\n      color: #414850;\n      font-family: \"Cascadia Mono\", Consolas, monospace;\n      font-size: 13px;\n      line-height: 1.65;\n      overflow-x: auto;\n    }\n\n    .source-list {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n      margin-top: 12px;\n    }\n\n    .action-button {\n      width: 100%;\n      min-height: 42px;\n      margin-top: 12px;\n      border: 1px solid rgba(156, 47, 36, 0.28);\n      border-radius: var(--radius);\n      background: #fff0dc;\n      color: var(--accent);\n      cursor: pointer;\n      font: inherit;\n      font-size: 14px;\n      font-weight: 900;\n      transition: transform 150ms ease, border-color 150ms ease, box-shadow 150ms ease;\n    }\n\n    .action-button:hover,\n    .action-button:focus-visible {\n      transform: translateY(-1px);\n      border-color: rgba(156, 47, 36, 0.50);\n      box-shadow: 0 12px 28px rgba(43, 35, 26, 0.13);\n      outline: none;\n    }\n\n    .modal-backdrop {\n      position: fixed;\n      inset: 0;\n      z-index: 20;\n      display: none;\n      place-items: center;\n      padding: 18px;\n      background: rgba(22, 25, 29, 0.58);\n    }\n\n    .modal-backdrop.is-open { display: grid; }\n\n    .modal {\n      width: min(860px, 100%);\n      max-height: min(760px, calc(100vh - 36px));\n      overflow: auto;\n      border: 1px solid rgba(255, 255, 255, 0.32);\n      border-radius: var(--radius);\n      background: var(--paper);\n      box-shadow: 0 24px 70px rgba(0, 0, 0, 0.28);\n    }\n\n    .modal-head {\n      position: sticky;\n      top: 0;\n      z-index: 1;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 12px;\n      padding: 14px 16px;\n      border-bottom: 1px solid var(--line);\n      background: rgba(255, 253, 248, 0.96);\n    }\n\n    .modal-head h2 {\n      margin: 0;\n      font-size: 21px;\n      line-height: 1.2;\n    }\n\n    .icon-button {\n      display: grid;\n      place-items: center;\n      flex: 0 0 auto;\n      width: 36px;\n      height: 36px;\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: #fff7e9;\n      color: var(--accent);\n      cursor: pointer;\n      font-size: 22px;\n      font-weight: 900;\n      line-height: 1;\n    }\n\n    .modal-body {\n      display: grid;\n      gap: 14px;\n      padding: 16px;\n    }\n\n    .result-grid {\n      display: grid;\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      gap: 10px;\n    }\n\n    .result-box {\n      padding: 12px;\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: #fffaf1;\n    }\n\n    .result-box span {\n      display: block;\n      color: var(--muted);\n      font-size: 12px;\n      font-weight: 900;\n      margin-bottom: 5px;\n    }\n\n    .result-box strong {\n      display: block;\n      color: var(--accent);\n      font-size: 24px;\n      line-height: 1.12;\n    }\n\n    .footer {\n      color: var(--muted);\n      font-size: 13px;\n      line-height: 1.65;\n      margin-top: 14px;\n    }\n\n    @media (max-width: 940px) {\n      .hero,\n      .main-grid,\n      .quick-grid,\n      .assumption-grid {\n        grid-template-columns: 1fr;\n      }\n\n      .topbar {\n        align-items: flex-start;\n        flex-direction: column;\n      }\n\n      .home-link { width: 100%; }\n    }\n\n    @media (max-width: 560px) {\n      .shell { width: min(100% - 20px, 1180px); padding-top: 18px; }\n      .hero-main,\n      .card,\n      .result-card { padding: 14px; }\n      .controls { grid-template-columns: 1fr; }\n      .result-grid { grid-template-columns: 1fr; }\n      table { min-width: 700px; }\n    }\n  </style>\n</head>\n<body>\n  <main class=\"shell\" id=\"top\">\n    <header class=\"topbar\">\n      <div class=\"brand\">\n        <div class=\"mark\" aria-hidden=\"true\">鍊</div>\n        <div>\n          <h1>RO樂園煉金製藥成本表</h1>\n          <p class=\"subtitle\">抵抗藥水成功率、材料成本、市價打平點與期望利潤整理</p>\n        </div>\n      </div>\n      <a class=\"home-link\" href=\"#top\">回頁首</a>\n    </header>\n\n    <section class=\"hero\" aria-label=\"重點結論\">\n      <div class=\"panel hero-main\">\n        <h2>54 等練功煉金也能做</h2>\n        <p>以怪物材料自取、紅黃藍魔力礦石全買、露天低標市價估算，抵抗藥水的打平成功率約 5.9%～17.4%。只要知識藥水與配藥有點高，期望值通常會比直接買成品漂亮。</p>\n      </div>\n      <div class=\"panel result-card\">\n        <span>預設成功率</span>\n        <div class=\"result-number\" id=\"heroRate\">66.5%</div>\n        <p>預設條件：Base 54 / Job 50，INT20、DEX51、LUK56，知識藥水10、配藥10，詩人 DEX60 魁儡、慈悲術 Job70、幸運頌歌全上。</p>\n      </div>\n    </section>\n\n    <dl class=\"quick-grid\" aria-label=\"市價結論\">\n      <div class=\"panel metric\">\n        <dt>水抵抗平均成本</dt>\n        <dd id=\"waterAvg\">531z</dd>\n        <small>市價低標 3,000z，材料自取時很有空間。</small>\n      </div>\n      <div class=\"panel metric\">\n        <dt>風抵抗平均成本</dt>\n        <dd id=\"windAvg\">531z</dd>\n        <small>市價低標 6,000z，是這組裡最甜的品項。</small>\n      </div>\n      <div class=\"panel metric\">\n        <dt>火抵抗平均成本</dt>\n        <dd id=\"fireAvg\">1,045z</dd>\n        <small>紅石全買也仍低於 4,000z 市價低標。</small>\n      </div>\n      <div class=\"panel metric\">\n        <dt>地抵抗平均成本</dt>\n        <dd id=\"earthAvg\">2,074z</dd>\n        <small>黃石貴，但市價也高，仍有期望利潤。</small>\n      </div>\n    </dl>\n\n    <section class=\"main-grid\">\n      <aside class=\"panel card\">\n        <h2>試算條件</h2>\n        <div class=\"controls\">\n          <label>Base 等級\n            <input id=\"baseLv\" type=\"number\" min=\"1\" max=\"150\" value=\"54\">\n          </label>\n          <label>Job 等級\n            <input id=\"jobLv\" type=\"number\" min=\"1\" max=\"70\" value=\"50\">\n          </label>\n          <label>知識藥水\n            <input id=\"learningPotion\" type=\"number\" min=\"0\" max=\"10\" value=\"10\">\n          </label>\n          <label>配藥\n            <input id=\"pharmacy\" type=\"number\" min=\"0\" max=\"10\" value=\"10\">\n          </label>\n          <label>詩人 DEX\n            <input id=\"bardDex\" type=\"number\" min=\"0\" max=\"99\" value=\"60\">\n          </label>\n          <label>慈悲術 Job\n            <input id=\"clementiaJob\" type=\"number\" min=\"1\" max=\"70\" value=\"70\">\n          </label>\n          <label>煉金 INT\n            <input id=\"baseInt\" type=\"number\" min=\"1\" max=\"99\" value=\"20\">\n          </label>\n          <label>煉金 DEX\n            <input id=\"baseDex\" type=\"number\" min=\"1\" max=\"99\" value=\"51\">\n          </label>\n          <label>煉金 LUK\n            <input id=\"baseLuk\" type=\"number\" min=\"1\" max=\"99\" value=\"56\">\n          </label>\n          <label>成功率覆寫\n            <input id=\"rateOverride\" type=\"number\" min=\"0\" max=\"100\" step=\"0.01\" placeholder=\"留空用公式\">\n          </label>\n        </div>\n\n        <div class=\"toggle-row\">\n          <label class=\"check\">計入煉金 Job 加成\n            <input id=\"jobBonus\" type=\"checkbox\" checked>\n          </label>\n          <label class=\"check\">詩人魁儡，能力補到 99 上限\n            <input id=\"marionette\" type=\"checkbox\" checked>\n          </label>\n          <label class=\"check\">慈悲術：天賜10 + floor(Job/10)\n            <input id=\"blessing\" type=\"checkbox\" checked>\n          </label>\n          <label class=\"check\">幸運頌歌 +30 LUK\n            <input id=\"gloria\" type=\"checkbox\" checked>\n          </label>\n        </div>\n        <button class=\"action-button\" id=\"bestBuildButton\" type=\"button\">計算最佳配點</button>\n        <p class=\"note\">魁儡的計算採「先魁儡再慈悲」，避免 DEX 超過 99 時浪費。最佳配點只優化 INT / DEX / LUK，STR / AGI / VIT 先保留 1。</p>\n      </aside>\n\n      <section class=\"panel card\">\n        <h2>抵抗藥水期望值</h2>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr>\n                <th>品項</th>\n                <th>自取材料</th>\n                <th>每次成本</th>\n                <th>市價</th>\n                <th>打平成功率</th>\n                <th>平均成功成本</th>\n                <th>每瓶期望差額</th>\n              </tr>\n            </thead>\n            <tbody id=\"potionRows\"></tbody>\n          </table>\n        </div>\n        <p class=\"note\">每瓶期望差額 = 市價 - 平均成功成本；未扣露天稅、時間成本，也未把怪物材料折成市價。</p>\n      </section>\n    </section>\n\n    <section class=\"assumption-grid\">\n      <div class=\"panel card\">\n        <h3>商店與交換成本</h3>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr><th>材料</th><th>估價</th><th>備註</th></tr>\n            </thead>\n            <tbody>\n              <tr><td>藥缽</td><td><strong>6z</strong></td><td>NPC 折扣價</td></tr>\n              <tr><td>空藥瓶</td><td><strong>5z</strong></td><td>NPC 折扣價</td></tr>\n              <tr><td>藍色魔力礦石</td><td><strong>342z</strong></td><td>NPC 折扣價</td></tr>\n              <tr><td>紅色魔力礦石</td><td><strong>684z</strong></td><td>用 2 顆藍石交換估</td></tr>\n              <tr><td>黃色魔力礦石</td><td><strong>1,368z</strong></td><td>用 4 顆藍石交換估</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n\n      <div class=\"panel card\">\n        <h3>製藥公式</h3>\n        <p class=\"formula\">成功率 = 知識藥水Lv * 1<br>+ 配藥Lv * 3<br>+ JobLv * 0.2<br>+ DEX * 0.1<br>+ LUK * 0.1<br>+ INT * 0.05<br>- 5</p>\n        <p class=\"note\">`-5` 是抵抗藥水係數。慈悲術依公開說明採天賜效果再加 floor(施放者 Job/10)。</p>\n      </div>\n\n      <div class=\"panel card\">\n        <h3>建議做法</h3>\n        <p class=\"note\">54 等若想兼顧練功與製藥，不必硬洗純製藥。只要配藥與知識夠高，水/風抵抗在目前市價下就很容易高於打平點。</p>\n        <p class=\"note\">優先順序可抓：風抵抗、水抵抗、地抵抗、火抵抗。真正變數是自打材料的時間和成品是否能成交。</p>\n      </div>\n    </section>\n\n    <section class=\"panel card\">\n      <h2>材料表</h2>\n      <div class=\"table-wrap\">\n        <table>\n          <thead>\n            <tr>\n              <th>藥水</th>\n              <th>每瓶材料</th>\n              <th>預設市價</th>\n              <th>商店/石頭成本</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr><td>火抵抗藥</td><td>藥缽x1、空藥瓶x1、傘蜥頸x2、紅色魔力礦石x1</td><td>4,000z</td><td>695z</td></tr>\n            <tr><td>水抵抗藥</td><td>藥缽x1、空藥瓶x1、人魚之心x3、藍色魔力礦石x1</td><td>3,000z</td><td>353z</td></tr>\n            <tr><td>地抵抗藥</td><td>藥缽x1、空藥瓶x1、巨大傑勒比結晶x2、黃色魔力礦石x1</td><td>7,980z</td><td>1,379z</td></tr>\n            <tr><td>風抵抗藥</td><td>藥缽x1、空藥瓶x1、蛾蝶蟲翅膀粉末x3、藍色魔力礦石x1</td><td>6,000z</td><td>353z</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <p class=\"footer\">資料來源：FTH / ROZDB 抵抗藥水材料頁、RO樂園巴哈製藥公式討論、iRO Wiki 煉金 Job 加成與慈悲術說明、露天截圖市價。這是期望值工具，不代表實際成交價或自打材料時間成本。</p>\n  </main>\n\n  <div class=\"modal-backdrop\" id=\"bestBuildModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"bestBuildTitle\">\n    <div class=\"modal\">\n      <div class=\"modal-head\">\n        <h2 id=\"bestBuildTitle\">最佳製藥配點</h2>\n        <button class=\"icon-button\" id=\"closeBestBuild\" type=\"button\" aria-label=\"關閉\">×</button>\n      </div>\n      <div class=\"modal-body\" id=\"bestBuildResult\"></div>\n    </div>\n  </div>\n\n  <script>\n    const potions = [\n      { key: \"fire\", name: \"火抵抗藥\", self: \"傘蜥頸x2\", cost: 695, market: 4000 },\n      { key: \"water\", name: \"水抵抗藥\", self: \"人魚之心x3\", cost: 353, market: 3000 },\n      { key: \"earth\", name: \"地抵抗藥\", self: \"巨大傑勒比結晶x2\", cost: 1379, market: 7980 },\n      { key: \"wind\", name: \"風抵抗藥\", self: \"蛾蝶蟲翅膀粉末x3\", cost: 353, market: 6000 }\n    ];\n\n    const ids = [\n      \"baseLv\", \"jobLv\", \"learningPotion\", \"pharmacy\", \"bardDex\", \"clementiaJob\",\n      \"baseInt\", \"baseDex\", \"baseLuk\", \"rateOverride\", \"jobBonus\", \"marionette\", \"blessing\", \"gloria\"\n    ];\n\n    const el = Object.fromEntries(ids.map(id => [id, document.getElementById(id)]));\n    const rows = document.getElementById(\"potionRows\");\n    const bestBuildModal = document.getElementById(\"bestBuildModal\");\n    const bestBuildResult = document.getElementById(\"bestBuildResult\");\n    const bestBuildButton = document.getElementById(\"bestBuildButton\");\n    const closeBestBuild = document.getElementById(\"closeBestBuild\");\n    const alchemistJobBonuses = {\n      int: [1, 9, 17, 23, 24, 29, 38],\n      dex: [2, 3, 8, 13, 19, 21, 25, 28, 32],\n      luk: []\n    };\n\n    function numberValue(input, fallback) {\n      const value = Number(input.value);\n      return Number.isFinite(value) ? value : fallback;\n    }\n\n    function clamp(value, min, max) {\n      return Math.min(max, Math.max(min, value));\n    }\n\n    function fmt(value) {\n      return Math.round(value).toLocaleString(\"zh-TW\") + \"z\";\n    }\n\n    function pct(value) {\n      return value.toFixed(2).replace(/\\.00$/, \"\") + \"%\";\n    }\n\n    function zeny(value) {\n      const sign = value > 0 ? \"+\" : value < 0 ? \"-\" : \"\";\n      return sign + Math.abs(Math.round(value)).toLocaleString(\"zh-TW\") + \"z\";\n    }\n\n    function statCostTo(target) {\n      let cost = 0;\n      for (let current = 1; current < target; current++) {\n        cost += Math.floor((current - 1) / 10) + 2;\n      }\n      return cost;\n    }\n\n    const statCosts = Array.from({ length: 100 }, (_, stat) => stat === 0 ? 0 : statCostTo(stat));\n\n    function totalStatPoints(baseLv) {\n      let points = 48;\n      for (let lv = 2; lv <= baseLv; lv++) {\n        points += Math.floor(lv / 5) + 3;\n      }\n      return points;\n    }\n\n    function countJobBonus(jobLv, thresholds) {\n      return thresholds.filter(level => jobLv >= level).length;\n    }\n\n    function getInputs() {\n      const alchemistJob = clamp(numberValue(el.jobLv, 50), 1, 70);\n      return {\n        baseLv: clamp(numberValue(el.baseLv, 54), 1, 150),\n        jobLv: alchemistJob,\n        learning: clamp(numberValue(el.learningPotion, 10), 0, 10),\n        pharmacy: clamp(numberValue(el.pharmacy, 10), 0, 10),\n        bardDex: clamp(numberValue(el.bardDex, 60), 0, 99),\n        clementiaJob: clamp(numberValue(el.clementiaJob, 70), 1, 70),\n        useJobBonus: el.jobBonus.checked,\n        useMarionette: el.marionette.checked,\n        useBlessing: el.blessing.checked,\n        useGloria: el.gloria.checked\n      };\n    }\n\n    function getFinalStats(baseStats, options = getInputs()) {\n      let int = baseStats.int;\n      let dex = baseStats.dex;\n      let luk = baseStats.luk;\n\n      const jobInt = options.useJobBonus ? countJobBonus(options.jobLv, alchemistJobBonuses.int) : 0;\n      const jobDex = options.useJobBonus ? countJobBonus(options.jobLv, alchemistJobBonuses.dex) : 0;\n      const jobLuk = options.useJobBonus ? countJobBonus(options.jobLv, alchemistJobBonuses.luk) : 0;\n      int += jobInt;\n      dex += jobDex;\n      luk += jobLuk;\n\n      const beforeMarionetteDex = dex;\n      let marionetteDex = 0;\n      if (options.useMarionette) {\n        marionetteDex = Math.min(Math.floor(options.bardDex / 2), Math.max(0, 99 - dex));\n        dex += marionetteDex;\n      }\n\n      const blessing = options.useBlessing ? 10 + Math.floor(options.clementiaJob / 10) : 0;\n      if (blessing) {\n        int += blessing;\n        dex += blessing;\n      }\n\n      const gloria = options.useGloria ? 30 : 0;\n      luk += gloria;\n\n      return { int, dex, luk, jobInt, jobDex, jobLuk, beforeMarionetteDex, marionetteDex, blessing, gloria };\n    }\n\n    function brewingRate(baseStats, options = getInputs()) {\n      const finalStats = getFinalStats(baseStats, options);\n      const rate = options.learning + options.pharmacy * 3 + options.jobLv * 0.2\n        + finalStats.dex * 0.1 + finalStats.luk * 0.1 + finalStats.int * 0.05 - 5;\n      return {\n        rate: clamp(rate, 0, 100),\n        rawRate: rate,\n        finalStats\n      };\n    }\n\n    function calculateRate() {\n      const override = Number(el.rateOverride.value);\n      if (Number.isFinite(override) && el.rateOverride.value.trim() !== \"\") {\n        return clamp(override, 0, 100);\n      }\n\n      return brewingRate({\n        int: clamp(numberValue(el.baseInt, 20), 1, 99),\n        dex: clamp(numberValue(el.baseDex, 51), 1, 99),\n        luk: clamp(numberValue(el.baseLuk, 56), 1, 99)\n      }).rate;\n    }\n\n    function findBestBuild() {\n      const options = getInputs();\n      const availablePoints = totalStatPoints(options.baseLv);\n      let best = null;\n\n      for (let int = 1; int <= 99; int++) {\n        for (let dex = 1; dex <= 99; dex++) {\n          const partialCost = statCosts[int] + statCosts[dex];\n          if (partialCost + statCosts[1] > availablePoints) continue;\n\n          for (let luk = 1; luk <= 99; luk++) {\n            const cost = partialCost + statCosts[luk];\n            if (cost > availablePoints) continue;\n\n            const result = brewingRate({ int, dex, luk }, options);\n            const score = result.rawRate * 100000 - cost;\n            if (!best || score > best.score) {\n              best = { int, dex, luk, cost, options, availablePoints, ...result, score };\n            }\n          }\n        }\n      }\n\n      return best;\n    }\n\n    function render() {\n      const rate = calculateRate();\n      const chance = Math.max(rate / 100, 0.0001);\n      document.getElementById(\"heroRate\").textContent = pct(rate);\n\n      rows.innerHTML = potions.map(potion => {\n        const breakEven = potion.cost / potion.market * 100;\n        const avg = potion.cost / chance;\n        const margin = potion.market - avg;\n        const ok = rate >= breakEven;\n        return `\n          <tr>\n            <td><strong>${potion.name}</strong></td>\n            <td>${potion.self}</td>\n            <td>${fmt(potion.cost)}</td>\n            <td>${fmt(potion.market)}</td>\n            <td>${pct(breakEven)}</td>\n            <td>${fmt(avg)}</td>\n            <td class=\"${ok ? \"good\" : \"bad\"}\">${ok ? \"+\" : \"\"}${fmt(margin)}</td>\n          </tr>\n        `;\n      }).join(\"\");\n\n      for (const potion of potions) {\n        const target = document.getElementById(potion.key + \"Avg\");\n        if (target) target.textContent = fmt(potion.cost / chance);\n      }\n    }\n\n    function renderBestBuild() {\n      const best = findBestBuild();\n      const current = brewingRate({\n        int: clamp(numberValue(el.baseInt, 20), 1, 99),\n        dex: clamp(numberValue(el.baseDex, 51), 1, 99),\n        luk: clamp(numberValue(el.baseLuk, 56), 1, 99)\n      }, best.options);\n      const chance = Math.max(best.rate / 100, 0.0001);\n      const currentChance = Math.max(current.rate / 100, 0.0001);\n      const rowsHtml = potions.map(potion => {\n        const bestAvg = potion.cost / chance;\n        const currentAvg = potion.cost / currentChance;\n        return `\n          <tr>\n            <td><strong>${potion.name}</strong></td>\n            <td>${fmt(bestAvg)}</td>\n            <td>${zeny(potion.market - bestAvg)}</td>\n            <td>${zeny(currentAvg - bestAvg)}</td>\n          </tr>\n        `;\n      }).join(\"\");\n\n      bestBuildResult.innerHTML = `\n        <div class=\"result-grid\">\n          <div class=\"result-box\"><span>最佳配點</span><strong>INT ${best.int}<br>DEX ${best.dex}<br>LUK ${best.luk}</strong></div>\n          <div class=\"result-box\"><span>抵抗藥水成功率</span><strong>${pct(best.rate)}</strong></div>\n          <div class=\"result-box\"><span>可用 / 已用點數</span><strong>${best.availablePoints}<br>${best.cost}</strong></div>\n        </div>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr><th>項目</th><th>INT</th><th>DEX</th><th>LUK</th></tr>\n            </thead>\n            <tbody>\n              <tr><td>基本配點</td><td>${best.int}</td><td>${best.dex}</td><td>${best.luk}</td></tr>\n              <tr><td>煉金 Job 加成</td><td>${best.finalStats.jobInt}</td><td>${best.finalStats.jobDex}</td><td>${best.finalStats.jobLuk}</td></tr>\n              <tr><td>魁儡 / 慈悲 / 幸運</td><td>${best.finalStats.blessing}</td><td>${best.finalStats.marionetteDex + best.finalStats.blessing}</td><td>${best.finalStats.gloria}</td></tr>\n              <tr><td>最終製藥能力</td><td><strong>${best.finalStats.int}</strong></td><td><strong>${best.finalStats.dex}</strong></td><td><strong>${best.finalStats.luk}</strong></td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr><th>藥水</th><th>最佳平均成本</th><th>對市價期望差額</th><th>比目前配點省</th></tr>\n            </thead>\n            <tbody>${rowsHtml}</tbody>\n          </table>\n        </div>\n        <p class=\"note\">計算條件：Base ${best.options.baseLv} / Job ${best.options.jobLv}，慈悲術 Job ${best.options.clementiaJob}，詩人 DEX ${best.options.bardDex}。最佳化只分配 INT / DEX / LUK，其餘三圍保留 1；若你還要保留練功 STR/AGI/VIT，請把「成功率覆寫」填入實測或手動調整配點。</p>\n      `;\n      bestBuildModal.classList.add(\"is-open\");\n      closeBestBuild.focus();\n    }\n\n    function closeModal() {\n      bestBuildModal.classList.remove(\"is-open\");\n      bestBuildButton.focus();\n    }\n\n    ids.forEach(id => el[id].addEventListener(\"input\", render));\n    ids.forEach(id => el[id].addEventListener(\"change\", render));\n    bestBuildButton.addEventListener(\"click\", renderBestBuild);\n    closeBestBuild.addEventListener(\"click\", closeModal);\n    bestBuildModal.addEventListener(\"click\", event => {\n      if (event.target === bestBuildModal) closeModal();\n    });\n    document.addEventListener(\"keydown\", event => {\n      if (event.key === \"Escape\" && bestBuildModal.classList.contains(\"is-open\")) closeModal();\n    });\n    render();\n  </script>\n</body>\n</html>\n";

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/' || url.pathname === '/index.html' || url.pathname === '/alchemist-potion-cost.html') {
      return new Response(html, {
        headers: {
          'content-type': 'text/html; charset=utf-8',
          'cache-control': 'public, max-age=60'
        }
      });
    }
    return new Response('Not found', { status: 404, headers: { 'content-type': 'text/plain; charset=utf-8' } });
  }
};
